const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let still=reduced;const motion=document.querySelector('#motion');function setMotion(){document.body.classList.toggle('still',still);motion.textContent='motion: '+(still?'off':'on');motion.setAttribute('aria-pressed',String(still))}setMotion();motion.addEventListener('click',()=>{still=!still;setMotion()});let ticking=false;function frame(){if(!still){document.querySelectorAll('[data-speed]').forEach(el=>{const r=el.getBoundingClientRect();if(r.top<innerHeight&&r.bottom>0){const offset=(innerHeight/2-(r.top+r.height/2))*Number(el.dataset.speed);el.style.transform=`translateY(${offset}px)`}})}ticking=false}addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(frame);ticking=true}},{passive:true});frame();let timer;function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>t.classList.remove('show'),2400)}document.querySelector('#scramble').addEventListener('click',()=>{const angle=Math.round(Math.random()*30-15);document.querySelector('.hero-art').style.rotate=angle+'deg';document.querySelector('.sticker').style.left=(innerWidth<700?5+Math.random()*20:45+Math.random()*20)+'%';document.querySelector('.orb').style.filter=`hue-rotate(${Math.random()*300}deg)`;toast('A different way of looking at things.')});const colors=['#b6a0d6','#eab5a3','#afc9bd','#aac2dc'];let color=0;document.querySelector('#color').addEventListener('click',()=>{color=(color+1)%colors.length;document.documentElement.style.setProperty('--purple',colors[color])});const names=['dramatic','more nothing','doing it again'];document.querySelectorAll('[data-track]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.track)-1;document.querySelector('#bandcamp').src=`https://bandcamp.com/EmbeddedPlayer/album=1375038273/size=small/bgcol=161616/linkcol=b8a0e8/track=${[129702393,1255524577,3059349913][i]}/transparent=true/`;document.querySelectorAll('[data-track]').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('#playing-label').textContent=names[i]+' / press play below';document.querySelector('#player').scrollIntoView({behavior:still?'instant':'smooth',block:'center'})}));
